javascript.code:
function makeCounter() {
  let count = 0
  return () => {
    count += 1
    return count
  }
}
const next = makeCounter()
next()
console.log(next())

typescript.code:
function makeCounter(): () => number {
  let count = 0
  return () => {
    count += 1
    return count
  }
}
const next = makeCounter()
next()
console.log(next())

